      },
      {
        "id": "platform-box",
        "type": "box",
        "pad": 40,
        "ai_reasoning": "Holds the on-platform tiles; the two sources stay outside so they read as external systems feeding in.",
        "layout": "column",
        "gap": 40,
        "align": "stretch",
        "children": [
          {
            "id": "bar",
            "type": "group",
            "layout": "row",
            "justify": "between",
            "children": [
              {
                "id": "db-platform",
                "type": "db-platform"
