          },
          {
            "id": "body",
            "type": "group",
            "layout": "row",
            "gap": 100,
            "children": [
              {
                "id": "data",
                "type": "group",
                "layout": "column",
                "gap": 60,
                "children": [
                  {
                    "id": "medallion-table",
