              },
              {
                "id": "answer",
                "type": "group",
                "layout": "column",
                "gap": 70,
                "children": [
                  {
                    "id": "genie",
                    "type": "genie",
                    "ai_reasoning": "One agent for data AND documents: the tables and the documents volume feed it, the app asks it."
                  },
                  {
                    "id": "databricks-apps-work",
                    "type": "databricks-apps-work",
                    "ai_reasoning": "The custom business app: it calls Genie Agent (data + documents) rather than a separate document bot."
                  }
                ]
              },
              {
                "id": "genie-one",
                "type": "genie-one",
                "ai_reasoning": "Business-user entry point; the persona pill is built into the tile."
              }
            ]
          }
        ]
      }
    ],
    "edges": [
      {
        "id": "e-pg-med",
        "from": "src-postgres@r",
