        "to": "genie@l",
        "flow": true,
        "label": "Query tables"
      },
      {
        "id": "e-vol-genie",
        "from": "uc-volume@r",
        "to": "genie@l",
        "flow": true,
        "label": "content search"
      },
      {
        "id": "e-app-genie",
        "from": "databricks-apps-work@t",
        "to": "genie@b",
        "label": "asks Genie"
      },
      {
        "id": "e-genie-one",
        "from": "genie@r",
        "to": "genie-one@l"
      }
    ]
  }
]
